head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > preventCopy]<br/>GridView 컴포넌트에서 복사(Ctrl+C) 및 잘라내기(Ctrl+X)를 차단할지 설정합니다. Body Cell 이 편집모드일때는 적용되지 않습니다.",
    "validation" : [
        "preventCopy='true' 이면 preventCopyColumn 속성은 무시됩니다. (preventCopyColumn 으로 특정 컬럼만 지정해도 컬럼 구분 없이 그리드 전체의 복사가 차단됩니다.)",
        "preventCopy='false' 일 때만 preventCopyColumn 에 지정한 컬럼의 데이터만 복사가 차단되고 나머지 컬럼은 복사됩니다.",
        "preventCopy='true' 일때 텍스트 드래그가 차단되므로(w2noselect) copyType='native' 기능을 정상적으로 사용할 수 없습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - 편집 가능한 GridView (gBody 4 Column, editType=text), 데이터 4건
//  - preventCopyColumn 으로 col2 컬럼만 복사 차단 지정 (preventCopy=false 일 때만 유효)
//  - preventCopy 는 con_preventCopy 선택값(미설정/true/false), copyType 은 con_copyType 선택값(default/native) 으로 생성
//    · 빈값("") 이면 해당 속성 자체를 제외
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    let conPreventCopy = con_preventCopy.getText();  // "" / "true" / "false"
    let conCopyType    = con_copyType.getValue();    // "" (default) / "native"

    let properties = {
        focusMode : "cell",
        preventCopyColumn : "col2"   // col2 컬럼만 복사 차단 (preventCopy=false 일 때만 유효)
    };
    // 미설정("") 일 때는 preventCopy 속성 자체를 제외 (기본값 false 동작)
    if (conPreventCopy !== "") {
        properties.preventCopy = conPreventCopy;
    }
    if (conCopyType !== "") {
        properties.copyType = conCopyType;
    }
    let cList = $c.gcm.createCList(properties);

    // 복사 이벤트(oncustomcopy/oncustomcut) 바인딩
    let eList = $c.gcm.createEList(["oncustomcopy", "oncustomcut"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblPreventCopy = (conPreventCopy === '') ? '미설정(기본 false)' : conPreventCopy;
    let lblCopyType = (conCopyType === '') ? 'default' : conCopyType;
    $c.gcm.createLabel('label="편집 가능 GridView 생성 / col2 컬럼에 preventCopyColumn 설정됨 (preventCopy=' + lblPreventCopy + ', copyType=' + lblCopyType + '). preventCopy=true 면 preventCopyColumn 무시하고 전체 차단 및 native 복사 불가, false 면 col2 만 차단"', '', 'label1');

    // dataList 생성 (column id 를 col1~col4 로 맞춤, 복사/드래그 확인용 텍스트 채움)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { col1 : "CopyText0_0", col2 : "CopyText0_1", col3 : "CopyText0_2", col4 : "CopyText0_3" },
        { col1 : "CopyText1_0", col2 : "CopyText1_1", col3 : "CopyText1_2", col4 : "CopyText1_3" },
        { col1 : "CopyText2_0", col2 : "CopyText2_1", col3 : "CopyText2_2", col4 : "CopyText2_3" },
        { col1 : "CopyText3_0", col2 : "CopyText3_1", col3 : "CopyText3_2", col4 : "CopyText3_3" }
    ]);

    // target 생성 (편집 가능 그리드 : gBody Column 에 editType="text")
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:480px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="preventCopy 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="name2(preventCopyColumn)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" editType="text"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" editType="text"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" editType="text"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col4" editType="text"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// con_preventCopy / con_copyType 변경 시 Target 재생성 안내 (con 변경은 Target 재생성 버튼으로 반영)
scwin.con_preventCopy_onchange = function () {
    // 별도 동작 없음 (Target 재생성 버튼 클릭 시 comp_init 에서 반영)
}



// 포커스된 그리드 셀의 값 조회 (사용자가 복사한 원본 셀 값)
//  - getFocusedRowIndex / getFocusedColumnIndex 로 포커스 셀 위치 → getCellDisplayData 로 셀 값 조회
//  - 포커스 없으면 빈 문자열 반환
scwin.getFocusedCellValue = function () {
    let rowIndex = target1.getFocusedRowIndex();
    let colIndex = target1.getFocusedColumnIndex();
    if (rowIndex === undefined || rowIndex === null || rowIndex < 0 || colIndex === undefined || colIndex === null || colIndex < 0) {
        return "";
    }
    return target1.getCellDisplayData(rowIndex, colIndex);
}



// 붙여넣기 대상(txa_pasteTarget) 값 변경 시점에 출력
//  - GridView 값(포커스된 복사 원본 셀 값) 과 붙여넣기 대상 값을 한 줄로 출력
//  - preventCopy=true 면 preventCopyColumn 무시·전체 차단되어 붙여넣기 대상 값이 빔
//  - preventCopy=false 면 col2(preventCopyColumn) 만 비고 나머지 컬럼은 그리드 값과 일치
scwin.txa_pasteTarget_onchange = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    bottom.setReturnValue("GridView 값 : " + scwin.getFocusedCellValue() + " / 붙여넣기 대상 값 : " + txa_pasteTarget.getValue());
}



// oncustomcopy 핸들러 (복사 시도 시 발생 — 출력 없음, no-op)
scwin.target1_oncustomcopy = function (e) {
}



// oncustomcut 핸들러 (잘라내기 시도 시 발생 — 출력 없음, no-op)
scwin.target1_oncustomcut = function (e) {
}
